  ('06ad7c04-4858-5c6e-9202-5b94e080ed49', null, (select id from public.skills where slug = 'read-g11-word-parts'), null, 'medium',
   $q$The prefix ambi- means "both" or "around," and the suffix -ous means "having the quality of." Why does the passage call the label "left-handed" "ambiguous"?$q$, $q$[{"text":"It is considered rude by many athletes and coaches.","is_correct":false,"misconception_token":"context-only-guess"},{"text":"It can be understood in more than one way for the same person.","is_correct":true},{"text":"It describes people who are equally skilled with both hands.","is_correct":false,"misconception_token":"confuses-similar-word"},{"text":"It is used only by researchers and never by athletes.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It can be understood in more than one way for the same person.$q$, $q$Ambiguous means open to more than one interpretation, and someone who writes right-handed but throws left-handed could be labeled either way. Equal skill with both hands is ambidextrous, a different ambi word.$q$, 'draft', 'dc3eaa1d-85e2-5b3d-979e-c317babdffc8')
