values
  ('4f934713-67f1-586b-986e-a07a3773213f', null, (select id from public.skills where slug = 'read-g11-word-parts'), null, 'medium',
   $q$The Latin prefix mal- means "bad" or "badly." What does it mean that a tree in poor soil may be "malnourished"?$q$, $q$[{"text":"It is poorly fed and lacks the nutrients it needs.","is_correct":true},{"text":"It is infected by a harmful fungus or virus.","is_correct":false,"misconception_token":"context-only-guess"},{"text":"It is receiving far more food than it can use.","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"It is growing too quickly for its roots.","is_correct":false,"misconception_token":"ignores-root-clues"}]$q$::jsonb, $q$It is poorly fed and lacks the nutrients it needs.$q$, $q$Mal plus nourished means "badly fed," and the passage adds "lacking the nutrients it needs." Infection is the tempting choice, but the passage presents poor nutrition as a different cause that only looks like infection.$q$, 'draft', '995df5ae-8188-5b3e-9d61-2a6ea1f2e03c')
